  S.key=[`8 ปี — ${ORIG[bg][1]} แห่งนครม่านหมอก`];try{S.era=null}catch(e){}const K=S.mw.fog=newK(bg);K.endB=R(66,78);if(bg==='orphan')K.anc=80;
